(7142353, 1094878, 30861, '<td valign="top">The scale on this is precious, it''s oddly whimsical. Decent job on matching the lighting too :-)</td>', 'The scale on this is precious, it''s oddly whimsical. Decent job on matching the lighting too :-)', '2013-12-13 16:27:30.000000', NULL, 1),
(7142354, 1094233, 30861, '<td valign="top">Almost excellent :-) The head needs to be a LITTLE bigger growing on the left side, there''s a head/neck mismatch that''s disconcerting. Lovely light :-)</td>', 'Almost excellent :-) The head needs to be a LITTLE bigger growing on the left side, there''s a head/neck mismatch that''s disconcerting. Lovely light :-)', '2013-12-13 16:29:01.000000', NULL, 1),
(7142355, 1094264, 30861, '<td valign="top">That''s MAJORLY got the pose of a Griffin! Beautiful work in its own right, doesn''t feel challenge-driven. Well done.</td>', 'That''s MAJORLY got the pose of a Griffin! Beautiful work in its own right, doesn''t feel challenge-driven. Well done.', '2013-12-13 16:30:14.000000', NULL, 1),
